def separate_paren_groups(paren_string: str) -> List[str]:
    groups = []
    group_start_index = 0
    current_depth = 0
    for i, char in enumerate(paren_string):
        if char == "(":
            current_depth += 1
        elif char == ")":
            current_depth -= 1
            if current_depth == 0:
                groups.append(paren_string[group_start_index:i+1])
                group_start_index = i+1
    return groups

