def max_value_on_paths(N, grid_values):
    dp = [[[0] * 2 for _ in range(N)] for _ in range(N)]

    for x, y, v in grid_values:
        dp[x][y][0] = max(dp[x][y][0], v)
        dp[x][y][1] = max(dp[x][y][1], v)

    for i in range(N):
        for j in range(N):
            if i > 0:
                dp[i][j][0] = max(dp[i][j][0], dp[i - 1][j][1] + dp[i][j][0])
            if j > 0:
                dp[i][j][1] = max(dp[i][j][1], dp[i][j - 1][0] + dp[i][j][1])

    return dp[N - 1][N - 1][0]

