def verify_isbn(isbn: str) -> str:
    isbn_digits = isbn.replace('-', '')
    checksum = 0
    for i, digit in enumerate(isbn_digits):
        if i % 2 == 0:
            checksum += int(digit)
        else:
            checksum += int(digit) * 3
    checksum = (10 - (checksum % 10)) % 10
    if checksum == int(isbn_digits[-1]):
        return "Right"
    else:
        return isbn_digits[:-1] + str(checksum)

