def vigenere_decrypt(key, ciphertext):
    plaintext = ''
    for i in range(len(ciphertext)):
        key_char = key[i % len(key)]
        ciphertext_char = ciphertext[i]
        if ciphertext_char.isalpha():
            key_char_index = ord(key_char.upper()) - ord('A')
            ciphertext_char_index = ord(ciphertext_char.upper()) - ord('A')
            plaintext_char_index = (ciphertext_char_index - key_char_index) % 26
            plaintext += chr(plaintext_char_index + ord('A'))
        else:
            plaintext += ciphertext_char
    return plaintext

